fn reverse(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();
    let mut result: Vec<i32> = Vec::with_capacity(n);
    
    let mut i: usize = 0;
    while i < n {
        result.push(a[n - 1 - i]);
        i += 1;
    }
    
    result
}